                                sb.append((char) code);
                                i += 5; // skip \uXXXX
                            } catch (NumberFormatException e) {
                                // Invalid hex, treat literally
                                sb.append('\\').append('u');
                                i++;
                            }
                        } else {
                            // Not enough characters for a full escape
                            sb.append('\\').append('u');
                            i++;
                        }
                        break;
                    default:
                        // Unknown escape sequence, keep the character as is
                        sb.append(next);
