public static String applyRelativePath(String path, String relativePath) {
    // If the relative path is actually absolute, just return it
    if (relativePath.startsWith("/")) {
        return relativePath;
    }
    // Determine if the original path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Extract the directory part of the original path
    String base = path;
    int lastSlash = base.lastIndexOf('/');
    if (lastSlash >= 0) {
        base = base.substring(0, lastSlash);
    }
    // Split the base path into components
    java.util.List<String> stack = new java.util.ArrayList<>();
    if (!base.isEmpty()) {
        String[] baseParts = base.split("/");
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                stack.add(part);
            }
        }
    }
    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    return result.toString();
}

